//! The rule tier's tables and checks (Bench plan B2, I-056).
//!
//! `content/chem/rules.json` holds reactions generated by
//! `tools/chemdb/build_rules.py` from six textbook rules, and the tables
//! those rules use: ions and their charges, the salts made of them, the
//! solubility rules, standard reduction potentials (the reactivity series)
//! and the acids. [`check`] re-derives each reaction's rule from the
//! equation alone, so the tests catch a wrong generator: an acid and a base
//! give their own salt and water, a metal displaces only a less reactive one,
//! a precipitate is insoluble by the table, and so on. See
//! `docs/loop/items/I-056/spec.md`.

use std::collections::{BTreeMap, BTreeSet};

use realgame_sim::formula::{parse_equation, parse_formula, Equation};
use serde::Deserialize;

use crate::Entry;

#[derive(Clone, Debug, Deserialize)]
pub struct Ion {
    pub formula: String,
    pub charge: i32,
    pub name: String,
}

#[derive(Clone, Debug, Deserialize)]
pub struct Salt {
    pub cation: String,
    pub n: u32,
    pub anion: String,
    pub m: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Solubility {
    Soluble,
    Slight,
    Insoluble,
}

#[derive(Clone, Debug, Deserialize)]
pub struct Acid {
    pub anion: String,
    pub protons: u32,
    pub oxidising: bool,
    pub strong: bool,
}

#[derive(Clone, Debug, Deserialize)]
pub struct Tables {
    pub ions: BTreeMap<String, Ion>,
    pub salts: BTreeMap<String, Salt>,
    pub solubility: BTreeMap<String, Solubility>,
    pub reduction_potentials_v: BTreeMap<String, f64>,
    pub metal_ions: BTreeMap<String, String>,
    pub margin_v: f64,
    pub water_first: Vec<String>,
    pub acids: BTreeMap<String, Acid>,
    pub hazards: BTreeMap<String, String>,
}

#[derive(Clone, Debug, Deserialize)]
pub struct Bottle {
    pub species: String,
    pub band: realgame_sim::tier::Tier,
}

#[derive(Deserialize)]
struct File {
    sources: BTreeMap<String, String>,
    tables: Tables,
    bottles: Vec<Bottle>,
}

/// The rule tier's tables, sources and added bottles.
pub struct RuleData {
    pub sources: BTreeMap<String, String>,
    pub tables: Tables,
    pub bottles: Vec<Bottle>,
}

impl RuleData {
    pub fn load() -> RuleData {
        let f: File =
            serde_json::from_str(crate::RULES_JSON).expect("content/chem/rules.json is valid");
        RuleData {
            sources: f.sources,
            tables: f.tables,
            bottles: f.bottles,
        }
    }

    /// The net charge of one formula unit: zero for every salt whose ions
    /// balance. `None` for a species that is not a salt of the table.
    pub fn charge(&self, formula: &str) -> Option<i32> {
        let s = self.tables.salts.get(formula)?;
        let q = |ion: &str| self.tables.ions[ion].charge;
        Some(q(&s.cation) * s.n as i32 + q(&s.anion) * s.m as i32)
    }

    /// Whether a salt's ions hold exactly the atoms of its formula.
    pub fn salt_atoms_match(&self, formula: &str) -> bool {
        let Some(s) = self.tables.salts.get(formula) else {
            return false;
        };
        let mut want = BTreeMap::new();
        for (ion, k) in [(&s.cation, s.n), (&s.anion, s.m)] {
            let Ok(a) = parse_formula(&self.tables.ions[ion].formula) else {
                return false;
            };
            for (el, n) in a {
                *want.entry(el).or_insert(0) += n * k;
            }
        }
        parse_formula(formula).is_ok_and(|got| got == want)
    }

    fn sol(&self, f: &str) -> Option<Solubility> {
        self.tables.solubility.get(f).copied()
    }

    fn salt(&self, f: &str) -> Option<&Salt> {
        self.tables.salts.get(f)
    }

    /// The salt of `cation` and `anion`, if the table has it.
    fn salt_of(&self, cation: &str, anion: &str) -> Option<&str> {
        self.tables
            .salts
            .iter()
            .find(|(_, s)| s.cation == cation && s.anion == anion)
            .map(|(f, _)| f.as_str())
    }

    fn e0(&self, metal: &str) -> Option<f64> {
        self.tables.reduction_potentials_v.get(metal).copied()
    }
}

fn set(terms: &[realgame_sim::formula::Term]) -> BTreeSet<String> {
    terms.iter().map(|t| t.formula.clone()).collect()
}

/// The single species of `s` that `pick` accepts, if exactly one does.
fn one<'a>(s: &'a BTreeSet<String>, pick: impl Fn(&str) -> bool) -> Option<&'a str> {
    let mut it = s.iter().filter(|f| pick(f));
    let f = it.next()?;
    it.next().is_none().then_some(f.as_str())
}

/// Checks a rule-tier entry against its rule, from the equation alone.
pub fn check(d: &RuleData, e: &Entry) -> Result<(), String> {
    let eq: Equation = parse_equation(&e.equation).map_err(|x| x.to_string())?;
    if !eq.is_balanced() {
        return Err("not balanced".into());
    }
    for t in eq.reactants.iter().chain(&eq.products) {
        if let Some(q) = d.charge(&t.formula) {
            if q != 0 {
                return Err(format!("{} carries charge {q}", t.formula));
            }
            if !d.salt_atoms_match(&t.formula) {
                return Err(format!("{}: its ions are not its atoms", t.formula));
            }
        }
    }
    let (l, r) = (set(&eq.reactants), set(&eq.products));
    let acid = |f: &str| d.tables.acids.contains_key(f);
    let soluble = |f: &str| d.sol(f) == Some(Solubility::Soluble);
    let rule = e.rule.as_deref().ok_or("no rule")?;
    let want_family = match rule {
        "acid_base" => "neutralisation",
        "metal_acid" => "metal_acid",
        "carbonate_acid" => "carbonate_acid",
        "fuel_burns" => "combustion",
        "precipitate" => "precipitation",
        "displacement" => "displacement",
        other => return Err(format!("unknown rule {other}")),
    };
    if e.family != want_family {
        return Err(format!("family {} for rule {rule}", e.family));
    }
    let need = |ok: bool, why: &str| if ok { Ok(()) } else { Err(why.to_string()) };
    match rule {
        "acid_base" => {
            need(l.len() == 2, "two reactants")?;
            let a = one(&l, acid).ok_or("no acid")?;
            let base = l.iter().find(|f| f.as_str() != a).unwrap();
            let anion = &d.tables.acids[a].anion;
            let (cation, water) = if base == "NH3" {
                ("NH4+", false)
            } else {
                let s = d.salt(base).ok_or("the base is not a salt")?;
                need(
                    s.anion == "OH-" || s.anion == "O-2",
                    "the base is not a hydroxide or an oxide",
                )?;
                (s.cation.as_str(), true)
            };
            let salt = d.salt_of(cation, anion).ok_or("no salt of these ions")?;
            let mut want = BTreeSet::from([salt.to_string()]);
            if water {
                want.insert("H2O".into());
            }
            need(r == want, "the products are not the salt and water")?;
            need(
                d.sol(salt) != Some(Solubility::Slight),
                "the salt is only slightly soluble: it coats and stops",
            )
        }
        "metal_acid" => {
            need(l.len() == 2, "two reactants")?;
            let a = one(&l, acid).ok_or("no acid")?;
            need(
                !d.tables.acids[a].oxidising,
                "an oxidising acid gives no hydrogen",
            )?;
            let metal = l.iter().find(|f| f.as_str() != a).unwrap();
            let e0 = d.e0(metal).ok_or("not a metal of the series")?;
            need(
                e0 <= -d.tables.margin_v,
                "the metal is not above hydrogen in the series",
            )?;
            need(
                !d.tables.water_first.contains(metal),
                "the metal reacts with the water first",
            )?;
            let ion = &d.tables.metal_ions[metal];
            let salt = d.salt_of(ion, &d.tables.acids[a].anion).ok_or("no salt")?;
            need(soluble(salt), "the salt must dissolve")?;
            need(
                r == BTreeSet::from([salt.to_string(), "H2".into()]),
                "the products are not the salt and hydrogen",
            )
        }
        "carbonate_acid" => {
            need(l.len() == 2, "two reactants")?;
            let a = one(&l, acid).ok_or("no acid")?;
            let carb = l.iter().find(|f| f.as_str() != a).unwrap();
            let s = d.salt(carb).ok_or("not a salt")?;
            need(
                s.anion == "CO3-2" || s.anion == "HCO3-",
                "not a carbonate or hydrogencarbonate",
            )?;
            let salt = d
                .salt_of(&s.cation, &d.tables.acids[a].anion)
                .ok_or("no salt")?;
            need(
                soluble(salt),
                "the salt must dissolve (else it coats and stops)",
            )?;
            need(
                r == BTreeSet::from([salt.to_string(), "H2O".into(), "CO2".into()]),
                "the products are not the salt, water and carbon dioxide",
            )
        }
        "fuel_burns" => {
            need(l.len() == 2 && l.contains("O2"), "a fuel and oxygen")?;
            let fuel = l.iter().find(|f| f.as_str() != "O2").unwrap();
            let atoms = parse_formula(fuel).map_err(|x| x.to_string())?;
            need(
                atoms.contains_key("C")
                    && atoms.contains_key("H")
                    && atoms.keys().all(|k| ["C", "H", "O"].contains(&k.as_str())),
                "the fuel is not made of C, H (and O)",
            )?;
            need(
                r == BTreeSet::from(["CO2".to_string(), "H2O".to_string()]),
                "complete burning gives carbon dioxide and water",
            )
        }
        "precipitate" => {
            need(l.len() == 2 && r.len() == 2, "two salts each side")?;
            let ls: Vec<&Salt> = l.iter().filter_map(|f| d.salt(f)).collect();
            need(ls.len() == 2, "two salts")?;
            for f in &l {
                need(soluble(f), &format!("{f} must dissolve"))?;
            }
            let (a, b) = (ls[0], ls[1]);
            need(
                a.cation != b.cation && a.anion != b.anion,
                "the salts share an ion",
            )?;
            let p1 = d.salt_of(&a.cation, &b.anion).ok_or("no swapped salt")?;
            let p2 = d.salt_of(&b.cation, &a.anion).ok_or("no swapped salt")?;
            need(
                r == BTreeSet::from([p1.to_string(), p2.to_string()]),
                "the products are not the swapped pairs",
            )?;
            let insol = [p1, p2]
                .iter()
                .filter(|f| d.sol(f) == Some(Solubility::Insoluble))
                .count();
            let sol = [p1, p2].iter().filter(|f| soluble(f)).count();
            need(
                insol == 1 && sol == 1,
                "exactly one new pair must be insoluble by the table",
            )
        }
        "displacement" => {
            need(l.len() == 2 && r.len() == 2, "a metal and a salt each side")?;
            let m1 = one(&l, |f| d.e0(f).is_some()).ok_or("no metal")?;
            let s = d
                .salt(l.iter().find(|f| f.as_str() != m1).unwrap())
                .ok_or("no salt")?;
            need(
                soluble(l.iter().find(|f| f.as_str() != m1).unwrap()),
                "the salt must dissolve",
            )?;
            let m2 = &d.tables.ions[&s.cation].formula;
            let (e1, e2) = (
                d.e0(m1).ok_or("no potential")?,
                d.e0(m2).ok_or("no potential")?,
            );
            need(
                e1 <= e2 - d.tables.margin_v,
                "the metal is not more reactive than the one in the salt",
            )?;
            need(
                !d.tables.water_first.iter().any(|w| w == m1),
                "the metal reacts with the water first",
            )?;
            let salt = d
                .salt_of(&d.tables.metal_ions[m1], &s.anion)
                .ok_or("no salt")?;
            need(soluble(salt), "the new salt must dissolve")?;
            need(
                r == BTreeSet::from([salt.to_string(), m2.clone()]),
                "the products are not the new salt and the displaced metal",
            )
        }
        _ => unreachable!(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{reduce_side, reduced, Codex, CodexTier, Hazard};
    use realgame_sim::tier::Tier;

    fn rule_entries(c: &Codex) -> Vec<&Entry> {
        c.entries
            .iter()
            .filter(|e| e.tier == CodexTier::Rule)
            .collect()
    }

    #[test]
    fn the_rule_tier_loads_with_its_rules() {
        let c = Codex::load();
        let rs = rule_entries(&c);
        assert!(rs.len() >= 300, "{} rule reactions", rs.len());
        assert_eq!(c.rules.len(), 6);
        for e in &rs {
            assert!(e.id.starts_with("rule_"), "{}", e.id);
            let r = c.rule_of(e).unwrap_or_else(|| panic!("{}: rule", e.id));
            assert_eq!(r.family, e.family, "{}", e.id);
            assert!(c.families.contains(&e.family), "{}", e.id);
            assert_eq!(e.check, "draft", "{}: rule reactions wait for review", e.id);
            assert!(
                e.band >= Tier::Seedling,
                "{}: no rule reaction at Sprout",
                e.id
            );
        }
        let d = RuleData::load();
        for r in &c.rules {
            assert!(d.sources.contains_key(&r.source), "{}", r.id);
            assert!(!r.text.is_empty() && r.text.ends_with('.'), "{}", r.id);
        }
        // Checked entries come first and keep their tier.
        let first_rule = c
            .entries
            .iter()
            .position(|e| e.tier == CodexTier::Rule)
            .unwrap();
        assert!(c.entries[..first_rule].iter().all(|e| e.rule.is_none()));
        assert_eq!(Codex::load_core().entries.len(), first_rule);
    }

    #[test]
    fn every_rule_reaction_balances_and_is_charge_neutral() {
        let c = Codex::load();
        let d = RuleData::load();
        for (f, _) in &d.tables.salts {
            assert_eq!(d.charge(f), Some(0), "{f}: charge");
            assert!(d.salt_atoms_match(f), "{f}: its ions are not its atoms");
        }
        for e in rule_entries(&c) {
            let eq = parse_equation(&e.equation).unwrap();
            assert!(eq.is_balanced(), "{}", e.id);
            for t in eq.reactants.iter().chain(&eq.products) {
                // A species is either a neutral salt of the table or a neutral
                // molecule or element (formulas carry no charge).
                if let Some(q) = d.charge(&t.formula) {
                    assert_eq!(q, 0, "{}: {}", e.id, t.formula);
                }
                assert!(!t.formula.contains(['+', '-']), "{}", e.id);
            }
        }
    }

    #[test]
    fn every_rule_reaction_passes_its_rule() {
        let c = Codex::load();
        let d = RuleData::load();
        let mut bad = Vec::new();
        for e in rule_entries(&c) {
            if let Err(why) = check(&d, e) {
                bad.push(format!("{} ({}): {why}", e.id, e.equation));
            }
        }
        assert!(bad.is_empty(), "{bad:#?}");
    }

    /// The checks catch a wrong reaction of each kind.
    #[test]
    fn the_rule_checks_reject_wrong_chemistry() {
        let d = RuleData::load();
        let entry = |rule: &str, family: &str, eq: &str| Entry {
            id: "x".into(),
            name: "x".into(),
            family: family.into(),
            band: Tier::Adept,
            equation: eq.into(),
            needs: vec![],
            heat: None,
            say: String::new(),
            short: None,
            source: String::new(),
            check: "draft".into(),
            hazard: None,
            tier: CodexTier::Rule,
            rule: Some(rule.into()),
        };
        let bad = [
            // Copper is below zinc: it cannot push zinc out.
            ("displacement", "displacement", "Cu + ZnSO4 -> CuSO4 + Zn"),
            // Silver is below hydrogen.
            ("metal_acid", "metal_acid", "2Ag + 2HCl -> 2AgCl + H2"),
            // Nitric acid oxidises; it gives no hydrogen.
            ("metal_acid", "metal_acid", "Mg + 2HNO3 -> Mg(NO3)2 + H2"),
            // Sodium nitrate and potassium chloride both dissolve: no solid.
            ("precipitate", "precipitation", "NaNO3 + KCl -> KNO3 + NaCl"),
            // A carbonate is not this rule's base.
            (
                "acid_base",
                "neutralisation",
                "2HCl + Na2CO3 -> 2NaCl + H2CO3",
            ),
            // Calcium sulfate is only slightly soluble.
            (
                "acid_base",
                "neutralisation",
                "Ca(OH)2 + H2SO4 -> CaSO4 + 2H2O",
            ),
            // Incomplete burning is not this rule.
            ("fuel_burns", "combustion", "2C3H6 + 6O2 -> 6CO + 6H2O"),
            // Calcium sulfate coats the chalk and stops it.
            (
                "carbonate_acid",
                "carbonate_acid",
                "CaCO3 + H2SO4 -> CaSO4 + H2O + CO2",
            ),
        ];
        for (rule, fam, eq) in bad {
            assert!(
                check(&d, &entry(rule, fam, eq)).is_err(),
                "{eq} passed {rule}"
            );
        }
        let good = entry("precipitate", "precipitation", "AgNO3 + KCl -> AgCl + KNO3");
        assert_eq!(check(&d, &good), Ok(()));
        assert!(d.e0("Mg").unwrap() < d.e0("Cu").unwrap());
        assert_eq!(d.sol("BaSO4"), Some(Solubility::Insoluble));
        assert_eq!(d.sol("NaNO3"), Some(Solubility::Soluble));
    }

    /// The Bench's bottles at each band: the core reactions' reactants at
    /// that band, plus the bottles the rule tier adds at their band.
    #[test]
    fn every_rule_reaction_is_makeable_from_its_bands_bottles() {
        let core = Codex::load_core();
        let d = RuleData::load();
        let mut shelf: BTreeMap<String, Tier> = BTreeMap::new();
        for e in &core.entries {
            for t in parse_equation(&e.equation).unwrap().reactants {
                let b = shelf.entry(t.formula).or_insert(e.band);
                *b = (*b).min(e.band);
            }
        }
        for b in &d.bottles {
            assert!(
                !shelf.contains_key(&b.species),
                "{} is already on the core shelf",
                b.species
            );
            shelf.insert(b.species.clone(), b.band);
        }
        let c = Codex::load();
        for e in rule_entries(&c) {
            for t in parse_equation(&e.equation).unwrap().reactants {
                let b = shelf
                    .get(&t.formula)
                    .unwrap_or_else(|| panic!("{}: no bottle of {}", e.id, t.formula));
                assert!(
                    *b <= e.band,
                    "{}: {} is a {:?} bottle, the reaction is {:?}",
                    e.id,
                    t.formula,
                    b,
                    e.band
                );
            }
        }
    }

    /// A rule reaction never repeats a checked one, and never has the
    /// reactants of one (so running those bottles always finds the checked
    /// reaction).
    #[test]
    fn no_rule_reaction_duplicates_or_shadows_core() {
        let core = Codex::load_core();
        let c = Codex::load();
        let core_keys: BTreeSet<_> = core
            .entries
            .iter()
            .map(|e| reduced(&parse_equation(&e.equation).unwrap()))
            .collect();
        let core_left: BTreeSet<_> = core_keys.iter().map(|k| reduce_side(&k.0)).collect();
        let core_ids: BTreeSet<_> = core.entries.iter().map(|e| e.id.as_str()).collect();
        let mut seen = BTreeSet::new();
        for e in rule_entries(&c) {
            let k = reduced(&parse_equation(&e.equation).unwrap());
            assert!(!core_keys.contains(&k), "{} repeats a core reaction", e.id);
            assert!(
                !core_left.contains(&reduce_side(&k.0)),
                "{} has the reactants of a core reaction",
                e.id
            );
            assert!(!core_ids.contains(e.id.as_str()), "{}", e.id);
            assert!(seen.insert(k), "{} appears twice", e.id);
        }
        // Running a core reaction's bottles still finds the core reaction.
        for e in &core.entries {
            let eq = parse_equation(&e.equation).unwrap();
            let (i, _) = c.run(&eq.reactants, &e.needs, Tier::Adept).unwrap();
            assert_eq!(c.entries[i].tier, CodexTier::Checked, "{}", e.id);
        }
    }

    #[test]
    fn corrosive_and_toxic_rule_reactions_carry_the_lab_badge() {
        let c = Codex::load();
        let d = RuleData::load();
        for (f, why) in &d.tables.hazards {
            assert!(
                why.contains("corrosive") || why.contains("toxic"),
                "{f}: {why}"
            );
        }
        for e in rule_entries(&c) {
            let eq = parse_equation(&e.equation).unwrap();
            let risky = eq
                .reactants
                .iter()
                .chain(&eq.products)
                .any(|t| d.tables.hazards.contains_key(&t.formula));
            if e.family == "combustion" {
                assert_eq!(e.hazard, Some(Hazard::Fire), "{}", e.id);
            } else if risky {
                assert_eq!(e.hazard, Some(Hazard::Lab), "{}", e.id);
            } else {
                assert_eq!(e.hazard, None, "{}", e.id);
            }
            // Nothing from the excluded list.
            for t in eq.reactants.iter().chain(&eq.products) {
                let a = parse_formula(&t.formula).unwrap();
                assert!(
                    !a.contains_key("F") && !a.contains_key("Hg") && !a.contains_key("Cr"),
                    "{}: {}",
                    e.id,
                    t.formula
                );
                assert!(!t.formula.contains("CN") && !t.formula.contains("ClO4"));
            }
        }
        // Strong acids and alkalis are on the list.
        for f in ["HCl", "HNO3", "H2SO4", "NaOH", "KOH"] {
            assert!(d.tables.hazards.contains_key(f), "{f}");
        }
    }

    #[test]
    fn every_rule_reaction_has_a_complete_show_record() {
        use crate::show::{Shows, Visible};
        let c = Codex::load();
        let s = Shows::build(&c);
        for e in rule_entries(&c) {
            let r = s
                .get(&e.id)
                .unwrap_or_else(|| panic!("{}: no record", e.id));
            assert!(r.dh.kj.is_some(), "{}: no ΔH", e.id);
            assert!(
                !r.visible.is_empty() || r.note.is_some(),
                "{}: nothing visible and no note",
                e.id
            );
            assert_ne!(r.dh.agrees, Some(false), "{}: heat class", e.id);
            for sp in &r.species {
                let sub = &s.substances[&sp.formula];
                // A species with a colour in its state shows it, sourced.
                if let Some(col) = sub.colour.get(&sp.state) {
                    assert_eq!(sp.colour.as_ref().map(|c| &c.src), Some(&col.src));
                    assert!(s.sources.contains_key(&col.src), "{}", e.id);
                }
            }
            match e.rule.as_deref() {
                Some("precipitate") => {
                    assert!(r.has(Visible::Precipitate), "{}", e.id);
                    for p in &r.precipitates {
                        assert!(
                            p.colour.is_some() && p.grain.is_some(),
                            "{}: {}",
                            e.id,
                            p.formula
                        );
                    }
                }
                Some("metal_acid") | Some("carbonate_acid") => {
                    assert!(r.has(Visible::Bubbles), "{}", e.id)
                }
                Some("fuel_burns") => {
                    assert!(r.has(Visible::Flame) && r.flame.is_some(), "{}", e.id)
                }
                Some("displacement") => assert!(r.has(Visible::Coating), "{}", e.id),
                _ => {}
            }
        }
    }
}
